// components/FUllPokemon.jsx
'use client'
import { useEffect, useState } from "react"
import Link from 'next/link'

export default function FUllPokemon({ numero }) {
    let [pokemon, setPokemon] = useState(null)

    // executa uma unica vez durante a montagem do componente
    useEffect(()=>{
        async function getPokemon(){
            let resposta = await fetch(`https://pokemon.danielpimentel.com.br/v1/pokemon/numero/${numero}`)
            let dados = await resposta.json()
            setPokemon(dados.pokemon)
        }
        getPokemon()
    }, [numero])

    if (!pokemon) {
        return <div className="p-6">Carregando...</div>
    }

    return (
        <div className="p-6">
            <h1 className="text-3xl font-bold capitalize mb-4">
                #{pokemon.numero} {pokemon.nome}
            </h1>

            <div className="flex gap-4 flex-wrap">
                <img className="h-50" src={pokemon.img} />
                <img className="h-50" src={pokemon.img_3d} />
                <img className="h-50" src={pokemon.img_shiny} />
            </div>

            <div className="mt-4">
                <p>Tipo: <span className="font-semibold capitalize">{pokemon.tipo.replaceAll(',', ', ')}</span></p>
                <p>Geração: <span className="font-semibold">{pokemon.geracao}</span></p>
                <p>Altura: <span className="font-semibold">{pokemon.altura}cm</span></p>
                <p>Peso: <span className="font-semibold">{pokemon.peso}kg</span></p>
                <p>Evoluções: <span className="font-semibold capitalize">{pokemon.evolucoes.replaceAll(',', ', ')}</span></p>
            </div>

            <div className="mt-4">
                <p>HP: <span className="font-semibold">{pokemon.hp}</span></p>
                <p>Ataque: <span className="font-semibold">{pokemon.atk}</span></p>
                <p>Defesa: <span className="font-semibold">{pokemon.def}</span></p>
                <p>Ataque Especial: <span className="font-semibold">{pokemon.spatk}</span></p>
                <p>Defesa Especial: <span className="font-semibold">{pokemon.spdef}</span></p>
                <p>Velocidade: <span className="font-semibold">{pokemon.speed}</span></p>
            </div>

            <Link
                href="/"
                className="font-bold cursor-pointer"
            >
                Voltar para a lista
            </Link>
        </div>
    )
}
